package com.nigson.experience.audit;

import com.nigson.experience.platform.AuditWriter;
import com.nigson.experience.platform.JdbcTrace;
import com.nigson.shared.security.ActorAssertion;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import static org.assertj.core.api.Assertions.*;

class AuditPersistenceTest {
    JdbcTemplate jdbc,bootstrap; TransactionTemplate tx; AuditWriter writer; AuditQueryService service; SimpleMeterRegistry metrics; UUID resource; ActorAssertion.Actor admin; long before;
    @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"audit PostgreSQL acceptance requires isolated Experience schema");if(!url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_EXPERIENCE_DB_REQUIRED");metrics=new SimpleMeterRegistry();metrics.config().meterFilter(new com.nigson.experience.platform.MetricPolicy());var ds=new JdbcTrace(new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime"),()->metrics);jdbc=new JdbcTemplate(ds);bootstrap=new JdbcTemplate(new DriverManagerDataSource(url,"nigson_bootstrap","mock-bootstrap"));tx=new TransactionTemplate(new DataSourceTransactionManager(ds));writer=new AuditWriter(jdbc,Clock.systemUTC(),metrics);service=new AuditQueryService(jdbc,new JdbcAuditQueryRepository(jdbc),new DataSourceTransactionManager(ds),metrics);resource=UUID.randomUUID();UUID party=UUID.randomUUID();String scope="audit.read_WITH_SIGNED_ADMIN";admin=new ActorAssertion.Actor(party,"https://identity.synthetic.invalid","synthetic-admin",null,Set.of("ADMIN"),Set.of(scope),Instant.now());before=jdbc.queryForObject("SELECT count(*) FROM experience.audit_record",Long.class);append("synthetic-audit-actor",Map.of("enabled",true,"email","private@example.invalid"),Map.of("state","ACTIVE","token","synthetic-secret"));append("synthetic-audit-actor-two",Map.of("version",1),Map.of("displayName","Private Name"));}
    private UUID append(String subject,Map<String,?> oldValue,Map<String,?> newValue){return tx.execute(s->writer.append(subject,com.nigson.shared.problem.AuditValues.ActorKind.USER,com.nigson.shared.problem.AuditValues.Action.FEATURE_ACTIVATION,com.nigson.shared.problem.AuditValues.Resource.FEATURE,resource,UUID.randomUUID(),com.nigson.shared.problem.AuditValues.Reason.CONFIGURATION_CHANGE,oldValue,newValue,null));}
    @Test void filtersPaginatesRedactsAndDoesNotMutateAppendOnlyAudit(){long count=jdbc.queryForObject("SELECT count(*) FROM experience.audit_record",Long.class);var start=Instant.now().minusSeconds(60);var end=Instant.now().plusSeconds(60);var q=new AuditValues.Query(resource,"FEATURE_ACTIVATION",start,end,0,1,"occurredAt,desc");var page=service.search(admin,q);assertThat(page.totalElements()).isEqualTo(2);assertThat(page.items()).hasSize(1);assertThat(page.items().getFirst().newValue().toString()).contains("redacted").doesNotContain("Private Name");var next=service.search(admin,new AuditValues.Query(resource,"FEATURE_ACTIVATION",null,null,1,1,"occurredAt,asc"));assertThat(next.items()).hasSize(1);assertThat(service.search(admin,new AuditValues.Query(resource,null,start,null,0,100,"occurredAt,desc")).totalElements()).isEqualTo(2);assertThat(service.search(admin,new AuditValues.Query(resource,null,null,end,0,100,"occurredAt,desc")).totalElements()).isEqualTo(2);var all=service.search(admin,new AuditValues.Query(resource,null,null,null,0,100,"actor,asc"));assertThat(all.items()).hasSize(2);assertThat(all.items().toString()).doesNotContain("private@example.invalid","synthetic-secret","Private Name");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record",Long.class)).isEqualTo(count);assertThat(metrics.get("nigson.audit.queries").tag("owner","experience").counter().count()).isEqualTo(5);assertThatThrownBy(()->jdbc.update("UPDATE experience.audit_record SET reason='tampered' WHERE resource_id=?",resource)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->jdbc.update("DELETE FROM experience.audit_record WHERE resource_id=?",resource)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
    @Test void exactAdminAndBoundedClosedFiltersAreRequired(){assertThatThrownBy(()->service.search(new ActorAssertion.Actor(admin.party(),admin.identityIssuer(),admin.identitySubject(),null,Set.of("SALES"),admin.scopes(),null),new AuditValues.Query(null,null,null,null,0,20,"occurredAt,desc"))).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->service.search(new ActorAssertion.Actor(admin.party(),admin.identityIssuer(),admin.identitySubject(),UUID.randomUUID(),admin.roles(),admin.scopes(),null),new AuditValues.Query(null,null,null,null,0,20,"occurredAt,desc"))).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->new AuditValues.Query(null,"DROP TABLE",null,null,0,20,"occurredAt,desc")).hasMessage("VALIDATION_ERROR");assertThatThrownBy(()->new AuditValues.Query(null,null,Instant.parse("2026-01-01T00:00:00Z"),Instant.parse("2026-01-02T00:00:00Z"),0,20,"id,desc")).hasMessage("VALIDATION_ERROR");assertThatThrownBy(()->new AuditValues.Query(null,null,Instant.parse("2024-01-01T00:00:00Z"),Instant.parse("2026-01-02T00:00:00Z"),0,20,"occurredAt,desc")).hasMessage("VALIDATION_ERROR");}
}
